node <<'NODE'
const fs = require('node:fs');
const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const report = JSON.parse(fs.readFileSync('../result-01.json', 'utf8'));
const changed = execFileSync('git', ['status', '--porcelain', '--untracked-files=all'], { encoding: 'utf8' })
    .split('\n').filter(Boolean).map(line => line.slice(3))
    .filter(file => !file.startsWith('dist/') && !file.startsWith('node_modules/')).sort();
assert.deepEqual(report.changed_files.slice().sort(), changed);
assert.equal(report.status, 'completed');
assert.deepEqual(report.questions, []);
assert.ok(report.checks.every(check => typeof check.command === 'string' && Number.isInteger(check.exit_code)));
console.log('Report valid; all 9 net source/documentation/test changes accounted for.');
NODE
